def parse_query_terms(frame: pd.DataFrame,
                      query: str,
                      query_fields: List[str]) -> Tuple[int, Dict[str, List[str]], bool]:
    search_terms: Dict[str, List[str]] = {}
    num_search_terms = 0
    term_centric = True

    for field in query_fields:
